import{_ as a,C as o,o as s,c as i,aj as e,G as n}from"./chunks/framework.BwH0p-pt.js";const y=JSON.parse('{"title":"Magic AI — System Prompts","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/magic-ai/system-prompts.md","filePath":"2.1/magic-ai/system-prompts.md","lastUpdated":1781079046000}'),d={name:"2.1/magic-ai/system-prompts.md"};function m(p,t,l,h,c,g){const r=o("ImagePopup");return s(),i("div",null,[t[0]||(t[0]=e('<h1 id="magic-ai-—-system-prompts" tabindex="-1">Magic AI — System Prompts <a class="header-anchor" href="#magic-ai-—-system-prompts" aria-label="Permalink to &quot;Magic AI — System Prompts&quot;">​</a></h1><blockquote><p><strong>Sidebar:</strong> Magic AI → <strong>System Prompts</strong><strong>URL:</strong> <code>/admin/magic-ai/system-prompts</code></p></blockquote><p>The <strong>System Prompts</strong> page controls the AI&#39;s <strong>personality</strong> — the voice, tone, and generation parameters that sit underneath every content request in UnoPim. Only one System Prompt is active at a time, so your entire catalog keeps a consistent voice.</p><h2 id="what-is-a-system-prompt" tabindex="-1">What is a System Prompt? <a class="header-anchor" href="#what-is-a-system-prompt" aria-label="Permalink to &quot;What is a System Prompt?&quot;">​</a></h2><p>A <em>System Prompt</em> is a preamble that Magic AI prepends to every user-facing prompt before sending the request to the model. It sets:</p><ul><li><strong>Tone</strong> — friendly vs. formal, concise vs. vivid, authoritative vs. casual.</li><li><strong>Temperature</strong> — how creative or deterministic the output is (0.0 = tight and repeatable, 1.0 = varied and inventive).</li><li><strong>Max Tokens</strong> — how long the response can be.</li></ul><p>If a <a href="./prompts.html"><strong>Prompt</strong></a> says <em>what</em> to write for a specific field (<em>&quot;write a product description mentioning <code>@name</code> and <code>@color</code>&quot;</em>), a <strong>System Prompt</strong> says <em>how</em> it should sound — and that &quot;how&quot; applies to every piece of content the system produces.</p><h2 id="what-does-this-page-do" tabindex="-1">What does this page do? <a class="header-anchor" href="#what-does-this-page-do" aria-label="Permalink to &quot;What does this page do?&quot;">​</a></h2><ul><li>Lists the 10 preset System Prompts that ship with UnoPim plus any custom ones you create.</li><li>Lets you <strong>create</strong>, <strong>edit</strong>, <strong>enable/disable</strong>, and <strong>delete</strong> System Prompts.</li><li>Enforces that only one System Prompt is active at a time — enabling a new one automatically disables the previous one.</li></ul>',9)),n(r,{src:"/assets/2.1/images/magic-ai/system-prompts.png",alt:"System Prompts"}),t[1]||(t[1]=e('<h2 id="where-the-active-system-prompt-is-applied" tabindex="-1">Where the active System Prompt is applied <a class="header-anchor" href="#where-the-active-system-prompt-is-applied" aria-label="Permalink to &quot;Where the active System Prompt is applied&quot;">​</a></h2><p>Every AI request in UnoPim flows through a unified pipeline where the active System Prompt is prepended as the personality layer.</p><p>Because the active System Prompt applies to <strong>every</strong> AI feature — wand icons, auto-translation, auto-enrichment, and the AI Agent — switching it instantly changes the voice of every AI output across the catalog.</p><h2 id="system-prompts-datagrid" tabindex="-1">System Prompts datagrid <a class="header-anchor" href="#system-prompts-datagrid" aria-label="Permalink to &quot;System Prompts datagrid&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>The name of the system prompt.</td></tr><tr><td><strong>Tone</strong></td><td>The conversational tone (e.g., Confident, Vivid, Brief).</td></tr><tr><td><strong>Max Tokens</strong></td><td>The maximum number of tokens for AI responses.</td></tr><tr><td><strong>Temperature</strong></td><td>The creativity level (lower = more focused, higher = more creative).</td></tr><tr><td><strong>Status</strong></td><td>Enabled or Disabled.</td></tr><tr><td><strong>Created At</strong></td><td>Date the system prompt was created.</td></tr><tr><td><strong>Updated At</strong></td><td>Date the system prompt was last modified.</td></tr><tr><td><strong>Actions</strong></td><td>Edit (pencil icon), Delete (trash icon).</td></tr></tbody></table><h2 id="preset-system-prompts" tabindex="-1">Preset System Prompts <a class="header-anchor" href="#preset-system-prompts" aria-label="Permalink to &quot;Preset System Prompts&quot;">​</a></h2><p>UnoPim ships with 10 preset System Prompts. Only one can be enabled at a time.</p><table tabindex="0"><thead><tr><th>Title</th><th>Tone</th><th>Temperature</th><th>Notes</th></tr></thead><tbody><tr><td>Authoritative Guide</td><td>Confident, assertive, instructional</td><td>0.65</td><td></td></tr><tr><td>Descriptive Storyteller</td><td>Vivid, rich, engaging</td><td>0.9</td><td></td></tr><tr><td>Concise Responder</td><td>Brief, to-the-point</td><td>0.5</td><td></td></tr><tr><td>Technical Expert</td><td>Precise, analytical</td><td>0.6</td><td></td></tr><tr><td>Casual Conversationalist</td><td>Informal, relaxed</td><td>0.75</td><td></td></tr><tr><td>Motivational Coach</td><td>Energetic, encouraging</td><td>0.85</td><td></td></tr><tr><td>Empathetic Listener</td><td>Warm, understanding</td><td>0.6</td><td></td></tr><tr><td>Witty Commentator</td><td>Clever, humorous</td><td>0.9</td><td></td></tr><tr><td>Professional Advisor</td><td>Formal, respectful</td><td>0.65</td><td></td></tr><tr><td>Friendly Assistant</td><td>Friendly, helpful, casual</td><td>0.7</td><td>Enabled by default</td></tr></tbody></table><h2 id="creating-a-system-prompt" tabindex="-1">Creating a System Prompt <a class="header-anchor" href="#creating-a-system-prompt" aria-label="Permalink to &quot;Creating a System Prompt&quot;">​</a></h2><p>Click the <strong>Create System Prompt</strong> button. Configure:</p><ul><li><strong>Title</strong> — The name that appears in the datagrid (e.g., <em>&quot;Luxury Brand Voice&quot;</em>).</li><li><strong>Tone description</strong> — A plain-language description of the voice. The model reads this at request time, so be specific: <em>&quot;Write in an understated, elegant tone. Use concise sentences. Avoid marketing hyperbole.&quot;</em></li><li><strong>Max Tokens</strong> — Caps response length. Lower values produce shorter, cheaper output; higher values give the model more room.</li><li><strong>Temperature</strong> — 0.0 to 1.0. Low values (0.3–0.5) are best for reliable, repeatable output; high values (0.8–1.0) add variety and flair.</li><li><strong>Status</strong> — Enabling this one automatically disables the currently-active System Prompt.</li></ul><h2 id="choosing-a-temperature" tabindex="-1">Choosing a temperature <a class="header-anchor" href="#choosing-a-temperature" aria-label="Permalink to &quot;Choosing a temperature&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Temperature</th><th>Best for</th></tr></thead><tbody><tr><td><strong>0.0 – 0.4</strong></td><td>Technical specs, SEO meta fields, reference content — where repeatability matters.</td></tr><tr><td><strong>0.5 – 0.7</strong></td><td>General product descriptions, category copy, everyday marketing content.</td></tr><tr><td><strong>0.8 – 1.0</strong></td><td>Lifestyle content, storytelling, blog-style copy — where variety and creativity shine.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Only one System Prompt can be active at a time. Enabling a new System Prompt automatically disables the previously active one. Pick a personality that matches the tone you want across the whole catalog — switching mid-flight will make older and newer content feel inconsistent.</p></div><h2 id="prompts-vs-system-prompts" tabindex="-1">Prompts vs. System Prompts <a class="header-anchor" href="#prompts-vs-system-prompts" aria-label="Permalink to &quot;Prompts vs. System Prompts&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Prompt</th><th>System Prompt</th></tr></thead><tbody><tr><td><strong>Scope</strong></td><td>Per field / per purpose</td><td>Global across the whole system</td></tr><tr><td><strong>Says</strong></td><td><em>What</em> to write</td><td><em>How</em> to write</td></tr><tr><td><strong>How many active</strong></td><td>As many as you&#39;ve created</td><td>Exactly one</td></tr><tr><td><strong>Placeholders</strong></td><td>Yes (<code>@attribute_code</code>)</td><td>No — written as plain instructions</td></tr><tr><td><strong>Typical change cadence</strong></td><td>Often — tuned per attribute, per use case</td><td>Rarely — tied to brand voice</td></tr></tbody></table><p>See <strong><a href="./prompts.html">Prompts</a></strong> for the per-field instruction layer that combines with the active System Prompt at generation time.</p>',17))])}const b=a(d,[["render",m]]);export{y as __pageData,b as default};
